/**
 * PhysicsPathfindingGrid - Worker-side 2.5D walkability grid for pathfinding
 *
 * Internal worker-side class for A* pathfinding.
 * Derives walkability from spatial grid data and BVH raycasts.
 * Uses lazy cell evaluation with BVH raycasts to determine walkability.
 * Cells are generated on-demand when pathfinding is requested.
 *
 * Note: This is a private worker-side class. Use NavigationGrid from
 * the main pathfinding module for the public API.
 *
 * @class PhysicsPathfindingGrid
 * @private
 * @short Worker-side 2.5D walkability grid
 * @category Pathfinding
 * @tags Navigation, Grid, Walkability, BVH, Worker
 */
export class PhysicsPathfindingGrid {
    /**
     * Create a new navigation grid.
     *
     * @param {Object} config - Configuration options.
     * @param {number} [config.cellSize=1.0] - Grid cell size in world units.
     * @param {number} [config.agentRadius=0.5] - Agent collision radius.
     * @param {number} [config.agentHeight=1.8] - Agent standing height.
     * @param {number} [config.maxSlope=0.785] - Maximum walkable slope in radians (~45 deg).
     * @param {number} [config.maxStepHeight=0.5] - Maximum step height between cells.
     * @param {number} [config.referenceGroundY=0] - Expected ground level Y. Used to find actual floor vs elevated surfaces.
     * @param {number} [config.maxWalkableHeight=1.5] - Maximum height above referenceGroundY for walkable cells.
     */
    constructor(config?: {
        cellSize?: number;
        agentRadius?: number;
        agentHeight?: number;
        maxSlope?: number;
        maxStepHeight?: number;
        referenceGroundY?: number;
        maxWalkableHeight?: number;
    });
    cellSize: number;
    agentRadius: number;
    agentHeight: number;
    maxSlope: number;
    maxStepHeight: number;
    referenceGroundY: number;
    maxWalkableHeight: number;
    minX: number;
    maxX: number;
    minZ: number;
    maxZ: number;
    _cells: Map<any, any>;
    _rayOrigin: any;
    _rayDir: any;
    _raycaster: any;
    _tempBox: any;
    /**
     * Configure grid parameters.
     *
     * @param {Object} config - Configuration object.
     * @returns {NavigationGrid} This instance for chaining.
     */
    set(config: any): NavigationGrid;
    /**
     * Generate navigation grid for an area.
     * Called lazily when pathfinding is requested.
     *
     * @param {THREE.Box3} bounds - Area to generate grid for.
     * @param {number} [padding=4] - Extra cells around bounds.
     * @param {number} [budget=Infinity] - Maximum cells to generate (for spreading over frames).
     * @returns {number} Number of cells generated.
     */
    generateForBounds(bounds: THREE.Box3, padding?: number, budget?: number): number;
    /**
     * Evaluate walkability for a single cell using BVH raycasts.
     *
     * @param {number} gx - Grid X coordinate.
     * @param {number} gz - Grid Z coordinate.
     * @returns {Object} Cell data.
     * @private
     */
    private _evaluateCell;
    /**
     * Check vertical clearance for agent at position.
     *
     * @param {number} x - World X coordinate.
     * @param {number} groundY - Ground Y coordinate.
     * @param {number} z - World Z coordinate.
     * @returns {boolean} True if enough clearance.
     * @private
     */
    private _checkClearance;
    /**
     * Check horizontal clearance for agent at position (detect walls at cell).
     * Raycasts INWARD from outside the cell to detect if obstacle surface is at cell position.
     *
     * @param {number} x - World X coordinate.
     * @param {number} groundY - Ground Y coordinate.
     * @param {number} z - World Z coordinate.
     * @param {Array} nearbyBodies - Already queried nearby bodies.
     * @returns {boolean} True if enough clearance (no wall at cell).
     * @private
     */
    private _checkHorizontalClearance;
    /**
     * Build neighbor connections for cells in range.
     * 8-connected grid with diagonal cost sqrt(2).
     *
     * @param {number} minGx - Minimum grid X.
     * @param {number} maxGx - Maximum grid X.
     * @param {number} minGz - Minimum grid Z.
     * @param {number} maxGz - Maximum grid Z.
     * @private
     */
    private _buildNeighbors;
    /**
     * Check if there's a wall between two cell positions.
     *
     * @param {number} x1 - Start X position.
     * @param {number} y1 - Start Y position (ground level).
     * @param {number} z1 - Start Z position.
     * @param {number} x2 - End X position.
     * @param {number} y2 - End Y position (ground level).
     * @param {number} z2 - End Z position.
     * @returns {boolean} True if wall detected.
     * @private
     */
    private _checkWallBetween;
    /**
     * Compute cell key from coordinates.
     * Uses string key to avoid hash collisions that cause sparse grids.
     *
     * @param {number} gx - Grid X coordinate.
     * @param {number} gz - Grid Z coordinate.
     * @returns {string} Cell key.
     * @private
     */
    private _hashCell;
    /**
     * Get cell at world position.
     *
     * @param {number} worldX - World X coordinate.
     * @param {number} worldZ - World Z coordinate.
     * @returns {Object|null} Cell data or null if not generated.
     */
    getCellAt(worldX: number, worldZ: number): any | null;
    /**
     * Find nearest walkable cell to a world position.
     * Uses spiral search outward from starting position.
     *
     * @param {number} worldX - World X coordinate.
     * @param {number} worldZ - World Z coordinate.
     * @param {number} [maxRadius=10] - Maximum search radius in cells.
     * @returns {Object|null} Nearest walkable cell or null.
     */
    findNearestWalkable(worldX: number, worldZ: number, maxRadius?: number): any | null;
    /**
     * Convert cell to world position.
     *
     * @param {Object} cell - Cell data.
     * @param {THREE.Vector3} [target] - Optional target vector.
     * @returns {THREE.Vector3} World position.
     */
    cellToWorld(cell: any, target?: THREE.Vector3): THREE.Vector3;
    /**
     * Clear all cells and reset grid.
     */
    clear(): void;
    /**
     * Get number of generated cells.
     *
     * @returns {number} Cell count.
     */
    get cellCount(): number;
}
